import{_ as t}from"./chunks/analytics_spotify_discovery.CA1B06lf.js";import{_ as a,c as o,b as s,a2 as r}from"./chunks/framework.BEqfOpL-.js";const i="/images/academy-analytics-hero.webp",n="/illustrations/academy-analytics-diagram.svg",w=JSON.parse('{"title":"Podcast Analytics Decoded: Which Metrics Actually Matter for SEO","description":"Choose useful podcast discovery metrics, understand what each analytics tool actually reports, and build a routine for reviewing keyword visibility alongside listening data.","frontmatter":{"description":"Choose useful podcast discovery metrics, understand what each analytics tool actually reports, and build a routine for reviewing keyword visibility alongside listening data."},"headers":[],"relativePath":"academy/podcast-analytics-decoded-which-metrics-actually-matter-for-seo.md","filePath":"academy/podcast-analytics-decoded-which-metrics-actually-matter-for-seo.md"}'),l={name:"academy/podcast-analytics-decoded-which-metrics-actually-matter-for-seo.md"};function c(p,e,d,h,m,u){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="podcast-analytics-decoded-which-metrics-actually-matter-for-seo" tabindex="-1">Podcast Analytics Decoded: Which Metrics Actually Matter for SEO <a class="header-anchor" href="#podcast-analytics-decoded-which-metrics-actually-matter-for-seo" aria-label="Permalink to &quot;Podcast Analytics Decoded: Which Metrics Actually Matter for SEO&quot;">​</a></h1><p>Download numbers dominate podcast conversations, but on their own they tell you very little about whether people can <em>find</em> your show. For example, a show with fewer downloads than another may still be gaining visibility for a useful search phrase. Each measure answers a different question.</p><p><img src="'+i+'" alt="A creator compares separate views of search, impressions and listening"></p><p>The difference is which metrics you look at, and — just as important — which tool you look at them in. This guide explains what Apple, Spotify, and PodSEO each report, what the platforms say they actually measure, and how to build a review routine that compares your show against its own baseline rather than against numbers nobody can verify.</p><p><strong>Start here:</strong> choose one question, record today&#39;s measurement and its source, then check it again over a comparable period. A small baseline is useful even if your show is new. You can add more measures as your questions become more specific.</p><table tabindex="0"><thead><tr><th>Your question</th><th>Start with</th><th>What it cannot tell you</th></tr></thead><tbody><tr><td>Can people find my show for this phrase?</td><td>Its observed position for the same keyword, platform and country</td><td>How many people listened because of that phrase</td></tr><tr><td>Are people engaging with an episode?</td><td>Platform plays and listening data, compared at the same episode age</td><td>How listeners found it on Apple Podcasts</td></tr><tr><td>Where was my show displayed on Spotify?</td><td>Discovery impressions by source</td><td>Plays attributed to a particular keyword</td></tr></tbody></table><h2 id="what-the-platforms-say-they-measure" tabindex="-1">What the Platforms Say They Measure <a class="header-anchor" href="#what-the-platforms-say-they-measure" aria-label="Permalink to &quot;What the Platforms Say They Measure&quot;">​</a></h2><p>Before choosing metrics, it helps to know what the platforms themselves say drives ranking. The documented picture is simpler than most &quot;algorithm&quot; articles suggest.</p><p><strong>Apple Podcasts search</strong> orders results by metadata (show name, channel name, episode titles), popularity (followers and plays in Apple Podcasts), and engagement from search results (plays and follows that happen after a search). Apple states that ratings, reviews, and shares are <em>not</em> factored directly into search results, while noting they &quot;influence whether people will listen or follow, and those factors influence the charts.&quot; Source: <a href="https://podcasters.apple.com/support/3686-search-on-apple-podcasts" target="_blank" rel="noreferrer">How Search works on Apple Podcasts</a>.</p><p><strong>Apple Podcasts charts</strong> reflect a mix of listening, follows, and completion rate. Source: <a href="https://podcasters.apple.com/support/3146-apple-podcasts-charts" target="_blank" rel="noreferrer">Apple Podcasts Charts</a>.</p><p><strong>Spotify</strong> emphasizes searchable titles and descriptions (the first 250 characters matter most), transcripts, chapters, and topic/guest tags, and notes that click-through from search influences relevance. It does not publish ranking weights. Source: <a href="https://creators.spotify.com/resources/grow/podcast-seo" target="_blank" rel="noreferrer">Words matter: podcast SEO on Spotify</a>.</p><p>Neither platform publishes a completion threshold or follower-conversion rate that guarantees a search boost. Choose your own baseline rather than treating an illustrative number as an algorithm rule.</p><h2 id="why-downloads-alone-mislead" tabindex="-1">Why Downloads Alone Mislead <a class="header-anchor" href="#why-downloads-alone-mislead" aria-label="Permalink to &quot;Why Downloads Alone Mislead&quot;">​</a></h2><p>Downloads count a file being requested. They don&#39;t tell you whether the listener found you through search, how much they listened, whether they followed, or whether they came back. Different measurement services also count differently (see <a href="/academy/why-multiple-podcast-trackers-are-a-recipe-for-disaster.html">why running multiple trackers causes problems</a>), so even the raw number is less absolute than it looks.</p><p>Downloads are useful for following download trends and comparing episode launches. Do not use them as the denominator for a platform listener or conversion ratio unless the measurements cover the same population and window.</p><img class="academy-visual-desktop" src="'+n+'" alt="Keyword positions, Spotify discovery impressions and Apple listening activity answer different questions; a rank or impression does not identify a play."><div class="academy-visual-mobile"><p class="academy-visual-mobile__title">Three questions, three different measures</p><p class="academy-visual-mobile__intro">Compare them; they are not one funnel.</p><ol><li><strong>Where do I rank?</strong><span>PodSEO: position by keyword and platform.</span></li><li><strong>Where was my show displayed?</strong><span>Spotify: impressions by discovery source.</span></li><li><strong>What listening activity happened?</strong><span>Apple: plays, follows and engaged listeners.</span></li></ol><p class="academy-visual-mobile__note">A rank or impression does not identify a play. Spotify Search includes charts and editorial exposure.</p></div><h2 id="metric-1-keyword-positions-podseo" tabindex="-1">Metric 1: Keyword Positions (PodSEO) <a class="header-anchor" href="#metric-1-keyword-positions-podseo" aria-label="Permalink to &quot;Metric 1: Keyword Positions (PodSEO)&quot;">​</a></h2><p>The most direct SEO metric is where you rank for the searches you care about, on each platform, over time. This is what PodSEO observes for you.</p><ul><li><a href="/features/keyword-tracker.html">Keyword Tracker</a> records your position for each tracked keyword on each platform and shows movement over time.</li><li><a href="/features/rankings.html">Rankings → Show and Episodes</a> compare positions across platforms for the same term.</li><li><a href="/features/show-visibility.html">Show Visibility</a> and <a href="/features/episode-visibility.html">Episode Visibility</a> surface the keywords you already rank for without tracking them first.</li></ul><p><strong>How to read positions:</strong> a position is a <em>finding</em> signal, not an <em>attribution</em> signal. Ranking #3 for &quot;beginner investing podcast&quot; means listeners who search that phrase can see you near the top. It does not tell you how many of them tapped play. Read positions alongside listening data rather than converting them into estimated listeners.</p><h2 id="metric-2-engagement-apple-podcasts-connect" tabindex="-1">Metric 2: Engagement (Apple Podcasts Connect) <a class="header-anchor" href="#metric-2-engagement-apple-podcasts-connect" aria-label="Permalink to &quot;Metric 2: Engagement (Apple Podcasts Connect)&quot;">​</a></h2><p>Apple&#39;s analytics report followers, listeners, engaged listeners (people who listened to at least 20 minutes or 40% of an episode), plays, time listened, top countries and cities, and episode comparisons by days since release. Source: <a href="https://podcasters.apple.com/support/5392-listener-analytics" target="_blank" rel="noreferrer">Apple listener analytics</a>.</p><p>Apple&#39;s analytics <strong>do not</strong> report how a listener found your show. There is no search-vs-browse acquisition breakdown, so don&#39;t build a measurement plan around one. What Apple <em>does</em> give you lines up neatly with what Apple says its search and charts consider: plays, follows, and how much of an episode people consume.</p><p><strong>Useful views:</strong></p><ul><li><strong>Followers over time</strong> — follows are one of Apple&#39;s named popularity and chart inputs.</li><li><strong>Engaged listeners ÷ listeners</strong> — Apple&#39;s own definition of meaningful consumption. Track the ratio per episode and compare episodes to each other, not to an external benchmark.</li><li><strong>Performance by days since release</strong> — lets you compare a new episode&#39;s first week against your own previous episodes at the same age.</li></ul><h2 id="metric-3-discovery-sources-spotify-for-creators" tabindex="-1">Metric 3: Discovery Sources (Spotify for Creators) <a class="header-anchor" href="#metric-3-discovery-sources-spotify-for-creators" aria-label="Permalink to &quot;Metric 3: Discovery Sources (Spotify for Creators)&quot;">​</a></h2><p>Spotify&#39;s Discovery analytics report <strong>impressions</strong> — how many times your show&#39;s content was shown to a user on a discovery surface — split by source: <strong>Home</strong> (recommendations, recently played shows, previews), <strong>Library</strong> (saved shows and playlists), and <strong>Search</strong>. It also reports conversion rate, plays, and average completion, which is where exposure turns into listening. Read the definition of the Search source carefully — Spotify says it covers &quot;search queries … top charts, and our editorial recommendations.&quot; Source: <a href="https://support.spotify.com/kw-en/creators/article/discovery-analytics/" target="_blank" rel="noreferrer">Spotify discovery analytics</a>.</p><p>Spotify&#39;s Search source mixes query results, charts and editorial exposure; it counts impressions, not listeners. Compare it with tracked positions to identify changes worth investigating. Even if both rise after a metadata edit, another release or promotion may have contributed. It does not attribute plays to a particular keyword.</p><p><a href="/images/analytics_spotify_discovery.webp" title="Open screenshot at full size"><img src="'+t+'" alt="Spotify Discovery report in PodSEO, with impressions grouped by source"></a></p><p><em>In Analytics, use the source breakdown to see where Spotify displayed your content. Search includes charts and editorial, as well as search queries.</em></p><p>The Engagement and Discovery reports above exist only for shows you&#39;ve claimed in Apple Podcasts Connect and Spotify for Creators. If your host submitted the show for you, see <a href="/academy/why-you-should-claim-your-podcast-on-apple-and-spotify.html">Why You Should Claim Your Podcast on Apple Podcasts and Spotify</a>.</p><h2 id="metric-4-ratings-and-reviews-apple-spotify" tabindex="-1">Metric 4: Ratings and Reviews (Apple, Spotify) <a class="header-anchor" href="#metric-4-ratings-and-reviews-apple-spotify" aria-label="Permalink to &quot;Metric 4: Ratings and Reviews (Apple, Spotify)&quot;">​</a></h2><p>Apple says ratings, reviews, and shares are not a direct search factor. They are still worth tracking, for two reasons.</p><p>Reviews provide qualitative feedback and can help prospective listeners decide whether a show is for them. A review count is not a measurement of plays, completion or returning listeners; read those in the platform reports.</p><p>PodSEO&#39;s <a href="/features/ratings-and-reviews.html">Ratings and Reviews</a> view tracks counts and averages per country so you can see review growth alongside ranking movement. To invite useful feedback, ask a specific question tied to the episode. Do not treat the response count as a conversion or completion metric.</p><h2 id="metric-5-charts-podseo-apple-spotify" tabindex="-1">Metric 5: Charts (PodSEO, Apple, Spotify) <a class="header-anchor" href="#metric-5-charts-podseo-apple-spotify" aria-label="Permalink to &quot;Metric 5: Charts (PodSEO, Apple, Spotify)&quot;">​</a></h2><p>Chart positions are separate from search. Apple documents listening, follows and completion for its charts; do not assume every platform uses the same formula. <a href="/features/my-charts.html">My Charts</a> tracks your chart positions over time; <a href="/features/all-charts.html">All Charts</a> lets you see who is charting in your category. Use chart movement to follow chart visibility; it does not tell you how many people discovered the show through a keyword.</p><h2 id="metrics-to-retire-or-relabel" tabindex="-1">Metrics to Retire (or Relabel) <a class="header-anchor" href="#metrics-to-retire-or-relabel" aria-label="Permalink to &quot;Metrics to Retire (or Relabel)&quot;">​</a></h2><p>A few metrics show up in podcast SEO advice with a precision the evidence doesn&#39;t support.</p><ul><li><strong>&quot;Completion rate above X% guarantees ranking improvement.&quot;</strong> Completion is a documented Apple chart input, but no threshold is published. Track your own completion trend per episode and compare against your own median.</li><li><strong>&quot;Healthy shows convert Y% of listeners to subscribers.&quot;</strong> No platform publishes a conversion benchmark. Track followers gained per episode over time and watch the trend, not a target.</li><li><strong>&quot;Search traffic from Google Podcasts.&quot;</strong> Google Podcasts was discontinued in 2024 and replaced by podcasts in YouTube Music. YouTube Studio reports views, watch time, and traffic sources for podcast videos; treat it as a video platform with its own analytics, not a substitute for the old Google Podcasts data. Source: <a href="https://blog.youtube/news-and-events/podcast-destination-on-youtube-music/" target="_blank" rel="noreferrer">YouTube&#39;s announcement</a>.</li><li><strong>&quot;Review velocity is weighted by the algorithm.&quot;</strong> See above: reviews are feedback and social proof, not a substitute for measured listening. A review campaign does not establish a search-ranking effect.</li></ul><p>If you do keep a benchmark from a third-party study, note its source, date, sample, and definition next to the number. If it&#39;s just an example, label it as one.</p><h2 id="a-review-routine-that-works" tabindex="-1">A Review Routine That Works <a class="header-anchor" href="#a-review-routine-that-works" aria-label="Permalink to &quot;A Review Routine That Works&quot;">​</a></h2><p>Because the platforms don&#39;t disclose weights, the most reliable approach is a consistent cadence and a baseline of your own.</p><p><strong>Weekly (10 minutes):</strong> open Keyword Tracker and note any keyword that moved more than a few positions on any platform. Check whether a recent title, description, or transcript change lines up with the movement.</p><p><strong>Per episode (first two weeks):</strong> in Apple&#39;s analytics, compare episode plays and engaged-listener share at the same days-since-release where available. Read follower growth separately at show level; it is not attributed to an episode. In Spotify, note impressions by Home / Library / Search source and the conversion rate.</p><p><strong>Monthly (30 minutes):</strong> review Show Visibility for newly ranked keywords you aren&#39;t tracking yet, check chart movement in My Charts, and look at review growth in Ratings and Reviews. Record three numbers — tracked keywords in the top 10, followers gained, engaged-listener ratio — so next month has a baseline.</p><p><strong>Example:</strong> a gardening show records that it appears at position 12 for “balcony tomatoes” on Apple Podcasts in the US on May 1. It also records its Apple follower total and the first-week plays of its latest episode. After updating the episode title, it checks the same search, country and episode-age window a month later. If the position changes, the creator notes the change alongside any new release or promotion rather than crediting the title alone. These numbers are illustrative, not a target.</p><p><strong>Quarterly:</strong> revisit your show keywords in <a href="/features/keyword-strategy.html">Keyword Strategy</a>. If a term hasn&#39;t moved in a quarter despite title and description changes, it may be too competitive for now; Keyword Strategy&#39;s search and AI suggestions help find adjacent terms with less competition.</p><p>Optimization results don&#39;t arrive on a fixed schedule. Use a review window that covers complete reporting periods and enough episodes for a useful comparison. Record other changes in that window; the time you allow is a planning choice, not a platform indexing deadline.</p><h2 id="competitive-benchmarking-relative-performance" tabindex="-1">Competitive Benchmarking: Relative Performance <a class="header-anchor" href="#competitive-benchmarking-relative-performance" aria-label="Permalink to &quot;Competitive Benchmarking: Relative Performance&quot;">​</a></h2><p>Your numbers exist in context. <a href="/features/competitive-analysis.html">Competitive Analysis</a> shows which keywords competitors rank for and where you overlap, which is a far better yardstick than a universal completion-rate figure. A niche interview show and a daily news show will have very different engagement profiles; comparing yourself to shows with a similar format and audience is the only comparison that means anything.</p><h2 id="put-this-into-practice" tabindex="-1">Put this into practice <a class="header-anchor" href="#put-this-into-practice" aria-label="Permalink to &quot;Put this into practice&quot;">​</a></h2><p>Pair your review with the <a href="/academy/platform-algorithm-deep-dive-how-spotify-vs-apple-podcasts-really-rank-shows.html">platform search guide</a> and the <a href="/academy/the-30-day-podcast-seo-challenge-a-step-by-step-action-plan.html">30-day action plan</a>. Use <a href="/features/keyword-tracker.html">Keyword Tracker</a> to follow selected search terms; keep using Apple, Spotify, and your host&#39;s analytics for listening and download data.</p><p>Explore <a href="https://podseo.com/features/search-visibility/?utm_source=help&amp;utm_medium=referral&amp;utm_campaign=academy&amp;utm_content=podcast-analytics-decoded-which-metrics-actually-matter-for-seo" target="_blank" rel="noreferrer">PodSEO Search Visibility</a> to see how it supports this work. You can sign up from the product page; check <a href="https://podseo.com/pricing/?utm_source=help&amp;utm_medium=referral&amp;utm_campaign=academy&amp;utm_content=podcast-analytics-decoded-which-metrics-actually-matter-for-seo" target="_blank" rel="noreferrer">current plans</a> for feature availability.</p><p>Use <a href="/features/analytics.html">Analytics</a> to read connected platform reports and compare episodes inside PodSEO. <a href="/features/analytics-connections.html">Connect your analytics</a> explains setup and source differences.</p>',56)])])}const g=a(l,[["render",c]]);export{w as __pageData,g as default};
